def load_result_limit():
    value = int(os.getenv("SUPPORT_RESULT_LIMIT", str(DEFAULT_RESULT_LIMIT)))
    if not 1 <= value <= 20:
        raise ValueError("SUPPORT_RESULT_LIMIT must be between 1 and 20")
    return value

def search_help(query, retriever):
    limit = load_result_limit()
    return retriever.search(query, limit=limit)

def get_adapter(self, url):
    """
    Returns the appropriate connection adapter for the given URL.

    :rtype: requests.adapters.BaseAdapter
    """
    for prefix, adapter in self.adapters.items():
        if url.startswith(prefix):
            return adapter

    # Nothing matches :-/
    raise InvalidSchema(f"No connection adapters were found for {url!r}")
